package br.com.fastfps.util; import java.nio.*; public final class NativeBufferUtils{private static final ThreadLocal<ByteBuffer>L=new ThreadLocal<ByteBuffer>(){protected ByteBuffer initialValue(){return ByteBuffer.allocateDirect(1048576).order(ByteOrder.nativeOrder());}};public static ByteBuffer getPooledByteBuffer(int c){ByteBuffer b=L.get();if(b.capacity()<c){b=ByteBuffer.allocateDirect(c).order(ByteOrder.nativeOrder());L.set(b);}b.clear();return b;}public static FloatBuffer getPooledFloatBuffer(int c){return getPooledByteBuffer(c*4).asFloatBuffer();}public static IntBuffer getPooledIntBuffer(int c){return getPooledByteBuffer(c*4).asIntBuffer();}private NativeBufferUtils(){}}
